"""Source-only bootstrap: one initial actual READY; no automatic respawn.
Original close is observed only under supervisor-created idle shutdown marker.
Pristine server files and benchmark client stay unchanged.
"""
import importlib.util
import json
import os
from pathlib import Path
import sys

sys.dont_write_bytecode = True


class ObservedInput:
    def __init__(self, stream, record):
        self.stream, self.record = stream, record

    def write(self, data):
        result = self.stream.write(data)
        if data == 'QUIT\n':
            self.record['quit_write_completed'] = True
        return result

    def flush(self):
        result = self.stream.flush()
        if self.record.get('quit_write_completed'):
            self.record['quit_flush_completed'] = True
        return result

    def __getattr__(self, name):
        return getattr(self.stream, name)


def install(module, evidence, marker):
    original_close = module.StrataEngine.close
    original_init = module.StrataEngine.__init__
    original_restart = module.StrataEngine.restart
    original_ensure = module.Service.ensure_loaded
    state = dict(ready=False, starts=0)
    active = {}

    def fatal(reason):
        print('[BENCH_FATAL] automatic engine restart/reload forbidden: ' + reason, flush=True)
        raise module.EngineDied('benchmark single-engine guard: ' + reason)

    def audit(event, args):
        if event == 'os.kill' and active and args[0] == active.get('pid'):
            active.setdefault('fallback_signals', []).append(int(args[1]))
    sys.addaudithook(audit)

    def guarded_init(engine, *args, **kwargs):
        lazy = kwargs.get('lazy', args[5] if len(args) > 5 else False)
        if state['ready']:
            fatal('new engine constructor after actual READY')
        if not lazy:
            state['starts'] += 1
            if state['starts'] != 1:
                fatal('second non-lazy start attempt')
        result = original_init(engine, *args, **kwargs)
        # Actual original constructor blocks until READY and sets ended=False.
        if engine.proc is not None and engine.ended is False:
            state['ready'] = True
        return result

    def guarded_restart(engine, tries=3):
        if state['ready']:
            fatal('restart after actual READY')
        return original_restart(engine, tries=1)

    def guarded_ensure(service):
        if state['ready'] and (not service.loaded() or service._vision_down()):
            fatal('Service.ensure_loaded would reload a failed/unloaded engine')
        return original_ensure(service)

    def observed_close(engine):
        if not marker.is_file():
            return original_close(engine)
        if marker.is_symlink() or marker.stat().st_size > 4096:
            fatal('invalid shutdown marker')
        context = json.loads(marker.read_text())
        proc = engine.proc
        if proc is None:
            return original_close(engine)
        if context.get('server_pid') != os.getpid() or context.get('engine_pid') != proc.pid or context.get('idle') is not True:
            fatal('shutdown marker does not identify idle owned engine')
        record = dict(pid=proc.pid, sid=os.getsid(proc.pid), method='original StrataEngine.close',
            quit_write_completed=False, quit_flush_completed=False, fallback_signals=[], complete=False)
        active.clear()
        active.update(record)
        original_stream = proc.stdin
        if original_stream is not None:
            proc.stdin = ObservedInput(original_stream, active)
        try:
            result = original_close(engine)
            active['engine_exit_code'] = proc.returncode
            active['complete'] = True
            active['normal_quit'] = (active['quit_write_completed'] and active['quit_flush_completed'] and
                                    proc.returncode == 0 and not active['fallback_signals'])
            return result
        except BaseException as error:
            active['error'] = repr(error)
            raise
        finally:
            evidence.write_text(json.dumps(active, indent=2) + '\n')
            proc.stdin = original_stream
            active.clear()

    module.StrataEngine.__init__ = guarded_init
    module.StrataEngine.restart = guarded_restart
    module.Service.ensure_loaded = guarded_ensure
    module.StrataEngine.close = observed_close
    return state


def main():
    server, evidence, marker = map(Path, sys.argv[1:4])
    sys.path.insert(0, str(server.parent.parent))
    spec = importlib.util.spec_from_file_location('upstream_bench_owned_server', server)
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    install(module, evidence, marker)
    sys.argv = [str(server), *sys.argv[4:]]
    return module.main()


if __name__ == '__main__':
    raise SystemExit(main())
